            try:
                historical_price = float(historical_price)
                current_price = float((terms or {}).get("unit_price"))
            except (TypeError, ValueError):
                continue
            if historical_price <= 0 or current_price <= 0:
                continue
            date_value = row.get("date") or row.get("quote_date") or row.get("order_date") or ""
            candidates.append((str(date_value), historical_price, current_price, row_id))
        if not candidates:
            return ""
        date_value, historical_price, current_price, row_id = max(candidates)
        change = (current_price / historical_price - 1) * 100
        date_text = f" dated {date_value}" if date_value else ""
        source = "RFQ quote" if row_id.startswith("quote:") else "purchase record"
        return (
            f"Our latest matched {source} lists EUR {historical_price:.2f}/unit{date_text} "
            f"({row_id}); your current quote is {change:+.1f}% against that benchmark."
        )

    def _supplier_economics(self, case, sid, standard):
        """Pass the published cost estimate into strategic-goal scoring when it matches this part."""
        if not sid or case.get("buyer", {}).get("category_goal") not in RELATIONSHIP_GOALS:
            return None
        parts = case.get("parts", [])
        if len(parts) != 1:
            return None
        estimate = self.researcher.supplier_cost(sid, parts[0], exact_only=True)
        if not estimate or estimate.get("unit_cost") is None:
            return None
        profile = next(
            (row for row in self._research.get("supplier_profiles", []) if row.get("supplier_id") == sid),
            {},
        )
        scorecard = next(
            (row for row in self._research.get("scorecards", []) if row.get("supplier_id") == sid),
            {},
        )
        rate = float(case["buyer"].get("interest_rate", 0.0))
        return {
            "full_cost": float(estimate["unit_cost"]),
            "interest_rate": rate,
            "usual_rate": rate,
            "ppm": float(scorecard.get("ppm") or standard.get("ppm_commitment") or 0),
            "standard": standard,
            "extra": 0.0,
            "source_id": estimate.get("id"),
            "source_confidence_pct": estimate.get("confidence_pct"),
            "supplier_profile": profile,
        }

    def _cost(self, case, terms, standard=None, sid=None):
        supplier = self._supplier_economics(case, sid, standard or {})
        return total_cost(case, terms, standard, supplier=supplier)

    def _state(self, case, sid, events):
        sheet_id, terms = standing(events)
        std = standard_terms(events)
        terms = complete_offer(case, terms) if terms.get("unit_price") is not None else {}
        cost = self._cost(case, terms, std, sid) if terms else math.inf
        valid = bool(terms) and must_haves_ok(case, terms, std)
        target_price = self.target_price(case, terms, sid)
        target_terms = self.offer_terms(case, terms, target_price, sid, standard=std) if terms else complete_offer(
            case, {"unit_price": target_price}
        )
        # Target cost is filled against this supplier's quoted standard terms below.
        target_cost = self._cost(case, target_terms, std, sid)
        # The actual ceiling is supplier-specific because standard terms affect total cost.
        ceiling = self.max_price_for_cost(case, terms or target_terms, std, self.reference_cost(case, {}), sid)
        floor = self.supplier_floor(case, sid)
        return {
            "sheet_id": sheet_id, "terms": terms, "standard": std, "cost": cost, "valid": valid,
            "target_price": min(target_price, ceiling), "target_cost": target_cost,
            "ceiling_price": ceiling, "minimum_price": floor,
        }

    def target_price(self, case, terms, sid=None):
        buyer = case["buyer"]
        current = buyer.get("current_unit_price")
        if current is None:
            alt = buyer.get("alternative") or {}
            current = (alt.get("terms") or {}).get("unit_price") or buyer.get("fallback_unit_price")
        if current is None:
            history = [
                row for row in self._research.get("purchase_history", [])
                if row.get("supplier_id") == sid and row.get("price") is not None
            ]
            history.sort(key=lambda row: row.get("date", ""), reverse=True)
            if history:
                current = history[0]["price"]
        if current is None:
            quotes = [row for row in self._research.get("quotes", []) if row.get("unit_price") is not None]
            quotes.sort(key=lambda row: row.get("quote_date", ""), reverse=True)
            current = quotes[0]["unit_price"] if quotes else (terms or {}).get("unit_price") or 1.0
        changes = [(e.get("weight", 0), e["delta_pct"]) for e in self._evidence if e.get("weight", 0) > 0]
        total_weight = sum(w for w, _ in changes)
        delta = sum(w * d for w, d in changes) if changes else 0.0
        if total_weight > 1.0:
            delta /= total_weight
        # Avoid extrapolating a stale or noisy basket into an unbounded price move.
        delta = min(12.0, max(-12.0, delta))
        goal_discount = {
            "leverage": 0.07, "routine": 0.04, "quality_first": 0.015,
            "stabilise": 0.02, "secure_supply": 0.015,
        }.get(buyer.get("category_goal"), 0.04)
        fair_reference = float(current) * (1 + delta / 100)
        target = fair_reference * (1 - goal_discount)
        if peer_quotes := self.recent_peer_quotes(case, sid):
            # A recent same-part RFQ is a useful market ceiling, even if the negotiation starts
            # with only one live supplier thread.
            target = min(target, float(peer_quotes[0]["unit_price"]))
        floor = self.supplier_floor(case, sid)
        if floor > 0 and buyer.get("category_goal") in RELATIONSHIP_GOALS:
            target = max(target, floor)
        return round(max(0.01, target), 2)

    def recent_peer_quotes(self, case, sid):
        """Return same-part quotes within one year of the latest package observation."""
        quotes = [
            row for row in self._research.get("quotes", [])
            if row.get("supplier_id") != sid and row.get("unit_price") is not None
            and isinstance(row.get("id"), str) and row["id"].startswith("quote:")
            and self.fact(case, row["id"])
        ]
        if not quotes:
            return []
        months = [self._month_number(e.get("end_month")) for e in self._evidence]
        months.extend(self._month_number(row.get("quote_date")) for row in quotes)
        current = max((month for month in months if month is not None), default=None)
        if current is not None:
            quotes = [
                row for row in quotes
                if (month := self._month_number(row.get("quote_date"))) is not None
                and 0 <= current - month <= 12
            ]
        return sorted(quotes, key=lambda row: float(row["unit_price"]))

    def supplier_floor(self, case, sid):
        """Sustainable-margin price floor for strategic cases, when an exact cost row exists."""
        buyer = case["buyer"]
        if buyer.get("category_goal") not in RELATIONSHIP_GOALS or not sid or len(case.get("parts", [])) != 1:
            return 0.0
        estimate = self.researcher.supplier_cost(sid, case["parts"][0], exact_only=True)
        if not estimate or estimate.get("unit_cost") is None:
            return 0.0
        margin = min(80.0, max(0.0, float(buyer.get("sustainable_margin_pct") or 0)))
        return round(float(estimate["unit_cost"]) / max(0.2, 1 - margin / 100), 2)

    def _batna(self, case, threads, states):
        choices = []
        alt = case["buyer"].get("alternative") or {}
        if alt.get("terms", {}).get("unit_price") is not None and must_haves_ok(case, alt["terms"]):
            c = self._cost(case, alt["terms"], sid=alt.get("supplier_id"))
            choices.append((c, "documented alternative"))
        for sid, events in threads.items():
            if sid not in live_threads({sid: events}):
                continue
            sheet_id, terms = standing(events)
            if not sheet_id or terms.get("unit_price") is None:
                continue
            std = standard_terms(events)
            if must_haves_ok(case, terms, std):
                choices.append((self._cost(case, terms, std, sid), f"live quote {sid}"))
        fallback = case["buyer"].get("fallback_unit_price")
        if fallback is not None:
            terms = self.offer_terms(case, {}, fallback)
            if must_haves_ok(case, terms):
                choices.append((self._cost(case, terms), "fallback supply"))
        if not choices:
            return {"cost": math.inf, "source": "no priced alternative"}
        cost, source = min(choices)
        return {"cost": cost, "source": source}

    def reference_cost(self, case, threads):
        return self._batna(case, threads, {})["cost"]

    def max_price_for_cost(self, case, template, standard, cap, sid=None, optimize_terms=True):
        if not math.isfinite(cap):
            return max(0.01, float((template or {}).get("unit_price") or case["buyer"].get("current_unit_price") or 1) * 2)
        base = dict(template or complete_offer(case, {"unit_price": 1.0}))
        low, high = 0.01, max(100.0, float(base.get("unit_price") or 1.0) * 8)
        for _ in range(48):
            mid = (low + high) / 2
            offer = self.offer_terms(case, base, mid, sid, optimize_terms, standard)
            if self._cost(case, offer, standard, sid) <= cap + 0.01:
                low = mid
            else:
                high = mid
        return round(low, 2)

    def offer_terms(self, case, current_terms, price, sid=None, optimize_terms=True, standard=None):
        """Complete an offer, then minimize its published total cost over allowed case options."""
        terms = complete_offer(case, {**(current_terms or {}), "unit_price": price})
        if not optimize_terms:
            return terms
        options = case.get("term_options", {})
        must_haves = case["buyer"].get("must_haves", [])
        for _ in range(2):
            changed = False
            for field in case.get("negotiable", []):
                if field == "unit_price" or not options.get(field):
                    continue
                constraints = [must for must in must_haves if must["field"] == field]
                candidates = [snap(case, field, value) for value in options[field]]
                candidates = list(dict.fromkeys(
                    value for value in candidates
                    if all(OPS[must["op"]](value, must["value"]) for must in constraints)
                ))
                if not candidates:
                    continue
                scored = []
                for value in candidates:
                    candidate = complete_offer(case, {**terms, field: value})
                    if must_haves_ok(case, candidate, standard):
                        scored.append((self._cost(case, candidate, standard, sid), str(value), value))
                if scored:
                    best = min(scored)[2]
                    if terms.get(field) != best:
                        terms[field] = best
                        changed = True
            if not changed:
                break
        return complete_offer(case, terms)

    def cap_offer(self, case, terms, standard, cap, sid=None, optimize_terms=True):
        if not math.isfinite(cap) or self._cost(case, terms, standard, sid) <= cap + 0.01:
            return terms
        ceiling = self.max_price_for_cost(case, terms, standard, cap, sid, optimize_terms)
        return self.offer_terms(
            case, terms, max(0.01, min(terms.get("unit_price") or ceiling, ceiling)), sid, optimize_terms, standard
        )

    def offer_packages(self, case, sid, primary, standard, batna, ceiling):
        """Offer up to three buyer-safe packages so suppliers can trade price against cash or term."""
        packages = [primary]
        options = case.get("term_options", {})
        allowed = case.get("negotiable", [])
        must_haves = case["buyer"].get("must_haves", [])
        premium = max(0.01, round(float(primary.get("unit_price") or 0) * 0.01, 2))

        def add_variant(variant):
            variant = complete_offer(case, variant)
            variant = self.cap_offer(case, variant, standard, batna, sid, optimize_terms=False)
            if not must_haves_ok(case, variant, standard):
                return
            if self._cost(case, variant, standard, sid) > batna + 0.01:
                return
            if variant not in packages and len(packages) < 3:
                packages.append(variant)

        if "payment_days" in allowed:
            candidates = sorted(options.get("payment_days", []))
            for must in must_haves:
                if must["field"] == "payment_days":
                    candidates = [value for value in candidates if OPS[must["op"]](value, must["value"])]
            if candidates:
                seller_favorable_days = candidates[0]
                if seller_favorable_days != primary.get("payment_days"):
                    variant = dict(primary)
                    variant["payment_days"] = seller_favorable_days
                    variant["unit_price"] = min(ceiling, float(primary.get("unit_price") or 0) + premium)
                    add_variant(variant)

        if "contract_months" in allowed and len(packages) < 3:
            horizon = round(12 * case["buyer"].get("horizon_years", 0))
            durations = [value for value in options.get("contract_months", []) if value <= horizon]
            if durations:
                longer = max(durations)
                if longer > primary.get("contract_months", 0):
                    variant = dict(primary)
                    variant["contract_months"] = longer
                    variant["unit_price"] = min(ceiling, float(primary.get("unit_price") or 0) + premium)
                    add_variant(variant)
        return packages

    def best_peer_quote(self, case, sid, states):
        peers = [
            (state["cost"], other, state, True)
            for other, state in states.items()
            if other != sid and state["sheet_id"] and state["terms"].get("unit_price") is not None

